import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.B8bWmLDN.js";const m=JSON.parse('{"title":"Diagnostics","description":"","frontmatter":{},"headers":[],"relativePath":"reference/diagnostics.md","filePath":"reference/diagnostics.md","lastUpdated":1786787297000}'),s={name:"reference/diagnostics.md"};function n(i,e,d,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;Diagnostics&quot;">​</a></h1><p>Every warning and error this emitter can report, with what causes it and how to fix it. Diagnostic codes appear in compiler output as <code>tsp-asyncapi/&lt;code&gt;</code>.</p><p>A common design principle across all of them: <strong>the emitter never silently drops or silently rewrites your intent.</strong> Anything it cannot represent is either omitted with a warning, or reported as an error.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><h3 id="duplicate-schema-key" tabindex="-1"><code>duplicate-schema-key</code> <a class="header-anchor" href="#duplicate-schema-key" aria-label="Permalink to &quot;`duplicate-schema-key`&quot;">​</a></h3><blockquote><p>Duplicate schema name: &#39;&lt;name&gt;&#39;. Check @friendlyName decorators and overlap with types in TypeSpec or service namespace.</p></blockquote><p>Two declarations resolved to the same <code>components.schemas</code> key. Typical causes: two <code>@friendlyName</code>s resolving to the same string, or a declared model whose name matches a template instantiation&#39;s derived name (e.g. declaring <code>model PageString</code> while also using <code>Page&lt;string&gt;</code>).</p><p><strong>Fix:</strong> rename one declaration, or give one of them a distinct <code>@friendlyName</code>. The emitter never renames either side automatically.</p><h3 id="unsupported-payload-type" tabindex="-1"><code>unsupported-payload-type</code> <a class="header-anchor" href="#unsupported-payload-type" aria-label="Permalink to &quot;`unsupported-payload-type`&quot;">​</a></h3><blockquote><p>This emitter does not support a &lt;kind&gt; here. Use a model, scalar, enum, union, or literal value instead.</p></blockquote><p>A property or payload position names a TypeSpec entity the schema layer cannot convert — an <code>Interface</code>, <code>Namespace</code>, <code>Operation</code>, and so on. The compiler itself does not reject this; only the emitter does.</p><p><strong>Fix:</strong> replace the reference with a model, scalar, enum, union, or literal type.</p><h3 id="unrepresentable-circular-reference" tabindex="-1"><code>unrepresentable-circular-reference</code> <a class="header-anchor" href="#unrepresentable-circular-reference" aria-label="Permalink to &quot;`unrepresentable-circular-reference`&quot;">​</a></h3><blockquote><p>This anonymous type refers back to itself with no named type in between. A plain (non-$ref) schema cannot express that cycle. Give the type a name so it can be referenced through $ref instead.</p></blockquote><p>An anonymous type cycles back to itself, e.g. <code>alias Foo = { a: Foo };</code>. Anonymous types inline (they have no <code>components.schemas</code> entry), and an inline schema cannot express a cycle.</p><p><strong>Fix:</strong> turn the anonymous type into a named <code>model</code>. Named types reference each other through <code>$ref</code>, which handles cycles fine.</p><h3 id="duplicate-message-key" tabindex="-1"><code>duplicate-message-key</code> <a class="header-anchor" href="#duplicate-message-key" aria-label="Permalink to &quot;`duplicate-message-key`&quot;">​</a></h3><blockquote><p>Duplicate message name: &#39;&lt;name&gt;&#39;. Two @message models resolve to the same components.messages key. Pass an explicit name to @message on one of them.</p></blockquote><p>Two <code>@message</code> models resolved to the same <code>components.messages</code> key. Typical causes: two same-named models in different namespaces (a message key drops the namespace prefix a schema key keeps), or two <code>@friendlyName</code>s resolving to the same string.</p><p>Two instantiations of one template that produce the same key are not reported — there is only one <code>@message</code> in the source, and both refer to the same emitted component.</p><p><strong>Fix:</strong> pass an explicit name to <code>@message</code> on one of them.</p><h3 id="duplicate-message-decorator" tabindex="-1"><code>duplicate-message-decorator</code> <a class="header-anchor" href="#duplicate-message-decorator" aria-label="Permalink to &quot;`duplicate-message-decorator`&quot;">​</a></h3><blockquote><p>@message is applied to this model more than once. Only one application takes effect, and the rest are discarded. Remove the extra @message.</p></blockquote><p><code>@message</code> is not repeatable. Stacking it silently keeps just one application, so the extra names never reach the document.</p><p><strong>Fix:</strong> remove the extra <code>@message</code>.</p><h3 id="duplicate-content-type-decorator" tabindex="-1"><code>duplicate-content-type-decorator</code> <a class="header-anchor" href="#duplicate-content-type-decorator" aria-label="Permalink to &quot;`duplicate-content-type-decorator`&quot;">​</a></h3><blockquote><p>@contentType is applied to this model more than once. A message carries one content type, so only one application takes effect and the rest are discarded. Remove the extra @contentType.</p></blockquote><p><code>@contentType</code> is not repeatable. A message has one <code>contentType</code> field, so stacking the decorator would silently discard every value but one.</p><p><strong>Fix:</strong> remove the extra <code>@contentType</code>.</p><h3 id="empty-content-type" tabindex="-1"><code>empty-content-type</code> <a class="header-anchor" href="#empty-content-type" aria-label="Permalink to &quot;`empty-content-type`&quot;">​</a></h3><blockquote><p>@contentType was given an empty media type. A blank media type names no format, so it cannot reach the emitted message. This @contentType was dropped, and the message falls back to the document defaultContentType. Give it a media type, such as &#39;application/json&#39;.</p></blockquote><p>An application of <a href="./decorators.html#contenttype"><code>@contentType</code></a> passed the empty string. A blank media type names no format, so the emitter cannot write it into the message.</p><p>The message falls back to the document <code>defaultContentType</code>, the same result an absent <code>@contentType</code> gives. The user typed the empty string on purpose, so that fallback is reported rather than silent.</p><p><strong>Fix:</strong> give the decorator a media type, such as <code>application/json</code>, or remove it.</p><h3 id="duplicate-headers-decorator" tabindex="-1"><code>duplicate-headers-decorator</code> <a class="header-anchor" href="#duplicate-headers-decorator" aria-label="Permalink to &quot;`duplicate-headers-decorator`&quot;">​</a></h3><blockquote><p>@headers is applied to this model more than once. Only one application takes effect, and the rest are discarded. Remove the extra @headers.</p></blockquote><p><code>@headers</code> is not repeatable. Stacking it silently keeps just one application, so the other headers models never reach the document.</p><p><strong>Fix:</strong> remove the extra <code>@headers</code>.</p><h3 id="duplicate-message-headers" tabindex="-1"><code>duplicate-message-headers</code> <a class="header-anchor" href="#duplicate-message-headers" aria-label="Permalink to &quot;`duplicate-message-headers`&quot;">​</a></h3><blockquote><p>This message takes its headers from two sources: a field marked @header, and a model given to @headers. There is no rule that picks one over the other, so no <code>headers</code> were emitted at all. Keep one of the two sources.</p></blockquote><p>A message declares headers twice: at least one field carries <code>@header</code>, and the model also carries <code>@headers</code>. The emitter defines no priority between the two, so it emits neither. The marked fields stay in the payload, so nothing you wrote disappears while the error is unresolved.</p><p><strong>Fix:</strong> keep one source. Move the marked fields into the <code>@headers</code> model, or drop the <code>@headers</code>.</p><h3 id="headers-not-object" tabindex="-1"><code>headers-not-object</code> <a class="header-anchor" href="#headers-not-object" aria-label="Permalink to &quot;`headers-not-object`&quot;">​</a></h3><blockquote><p>The model &#39;&lt;name&gt;&#39; given to @headers is backed by an array. AsyncAPI requires the headers schema to be a key/value map, so no <code>headers</code> were emitted. Pass a model with properties instead.</p></blockquote><p>The model given to <code>@headers</code> emits <code>type: &quot;array&quot;</code> — it <code>is</code> an array, or it extends one. AsyncAPI requires the <code>headers</code> schema to describe a key/value map.</p><p><strong>Fix:</strong> pass a model with properties, or a <code>Record&lt;T&gt;</code>-backed model. Both emit an object schema.</p><h3 id="content-type-header-conflict" tabindex="-1"><code>content-type-header-conflict</code> <a class="header-anchor" href="#content-type-header-conflict" aria-label="Permalink to &quot;`content-type-header-conflict`&quot;">​</a></h3><blockquote><p>The header &#39;&lt;name&gt;&#39; names the message content type, and this message also carries @contentType. AsyncAPI has one field for the content type, so two sources for it are ambiguous. Remove the @header field and keep @contentType.</p></blockquote><p>A header field is named <code>content-type</code> (the comparison uses the emitted wire name and ignores case), and the same message also carries <code>@contentType</code>. AsyncAPI keeps the content type in its own message field, so the two sources cannot both be honoured. <code>@typespec/http</code> reclassifies such a header because HTTP has no other way to state it; this emitter does have <code>@contentType</code>, so it reports instead of choosing.</p><p>The check covers both headers mechanisms. The field may carry <code>@header</code> on the message model, or it may be a property of the model given to <code>@headers</code>, including a property that model inherits.</p><p><strong>Fix:</strong> remove the header field and keep <code>@contentType</code>.</p><h3 id="duplicate-correlation-id-decorator" tabindex="-1"><code>duplicate-correlation-id-decorator</code> <a class="header-anchor" href="#duplicate-correlation-id-decorator" aria-label="Permalink to &quot;`duplicate-correlation-id-decorator`&quot;">​</a></h3><blockquote><p>@correlationId is applied to this model more than once. Only one application takes effect, and the rest are discarded. Remove the extra @correlationId.</p></blockquote><p><code>@correlationId</code> is not repeatable. Stacking it silently keeps just one application, so the other locations never reach the document.</p><p><strong>Fix:</strong> remove the extra <code>@correlationId</code>.</p><h3 id="invalid-correlation-id-location" tabindex="-1"><code>invalid-correlation-id-location</code> <a class="header-anchor" href="#invalid-correlation-id-location" aria-label="Permalink to &quot;`invalid-correlation-id-location`&quot;">​</a></h3><blockquote><p>&#39;&lt;location&gt;&#39; is not a legal correlation id location, so no <code>correlationId</code> was emitted. Write &#39;$message.header#&#39; or &#39;$message.payload#&#39;, each optionally followed by a JSON Pointer, such as &#39;$message.header#/MQMD/CorrelId&#39;.</p></blockquote><p>The location does not match the AsyncAPI runtime expression grammar. The expression starts with <code>$message.header</code> or <code>$message.payload</code> and is followed by a <code>#</code>. Everything after the <code>#</code> is a JSON Pointer, so it is either empty or starts with <code>/</code>.</p><p>The <code>#</code> is required. The prose ABNF of the specification reads as if the fragment were optional, but the normative JSON Schema of the specification requires it, and the official AsyncAPI parser rejects a document that carries the bare <code>$message.header</code>.</p><p>Only the format is checked: the pointer may name a path no schema declares, which AsyncAPI&#39;s own examples do.</p><p><strong>Fix:</strong> write a location the grammar accepts, such as <code>$message.header#/correlationId</code>.</p><h3 id="empty-message-example" tabindex="-1"><code>empty-message-example</code> <a class="header-anchor" href="#empty-message-example" aria-label="Permalink to &quot;`empty-message-example`&quot;">​</a></h3><blockquote><p>This @messageExample carries neither <code>headers</code> nor <code>payload</code>, so it shows nothing about the message. This example was dropped. Give it at least one of the two.</p></blockquote><p>An application of <code>@messageExample</code> gave an empty value, or gave only <code>name</code> and <code>summary</code>. A Message Example Object with no content says nothing about the message.</p><p><strong>Fix:</strong> give the example a <code>headers</code> value, a <code>payload</code> value, or both.</p><h3 id="empty-tag-name" tabindex="-1"><code>empty-tag-name</code> <a class="header-anchor" href="#empty-tag-name" aria-label="Permalink to &quot;`empty-tag-name`&quot;">​</a></h3><blockquote><p>@asyncTag was given an empty name. The <code>name</code> of an AsyncAPI Tag Object is required, and no consumer can match a blank one. This tag was dropped. Give it a name.</p></blockquote><p>An application of <a href="./decorators.html#asynctag"><code>@asyncTag</code></a> passed the empty string as the tag name. <code>name</code> is required on an AsyncAPI Tag Object, so a blank one names nothing a consumer can match.</p><p><strong>Fix:</strong> give the tag a name.</p><h3 id="conflicting-tag-metadata" tabindex="-1"><code>conflicting-tag-metadata</code> <a class="header-anchor" href="#conflicting-tag-metadata" aria-label="Permalink to &quot;`conflicting-tag-metadata`&quot;">​</a></h3><blockquote><p>Tag &#39;&lt;name&gt;&#39; is declared more than once here, with a different &#39;&lt;field&gt;&#39;. AsyncAPI emits one Tag Object per name on an object, so only one of the two values can be kept. The first one in source order was kept. Merge the @asyncTag applications into one, or give them different names.</p></blockquote><p>Two applications of <a href="./decorators.html#asynctag"><code>@asyncTag</code></a> on one target name the same tag and give one of its fields two different values. AsyncAPI emits one Tag Object per name on an object, so one of the two values would have to be dropped. The emitter reports the ambiguity rather than choosing silently.</p><p>Applications that set <em>different</em> fields merge instead, and so do a built-in <code>@tag</code> and an <code>@asyncTag</code> of the same name. The same name on two <em>different</em> targets is never a conflict: AsyncAPI gives every object its own independent <code>tags</code> array.</p><p><strong>Fix:</strong> merge the two applications into one, or give them different names.</p><h3 id="duplicate-server-name" tabindex="-1"><code>duplicate-server-name</code> <a class="header-anchor" href="#duplicate-server-name" aria-label="Permalink to &quot;`duplicate-server-name`&quot;">​</a></h3><blockquote><p>Duplicate server name: &#39;&lt;name&gt;&#39;. Each @server on a namespace needs its own name, because the name is the key of that server in the emitted document. This @server was dropped, and the first one with this name in source order was kept.</p></blockquote><p>Two <code>@server</code> applications on the same namespace share a name. The name is the key of the <code>servers</code> map, so the two would collide. The emitter never picks one silently.</p><p><strong>Fix:</strong> Give one of them a different name.</p><h3 id="empty-server-field" tabindex="-1"><code>empty-server-field</code> <a class="header-anchor" href="#empty-server-field" aria-label="Permalink to &quot;`empty-server-field`&quot;">​</a></h3><blockquote><p>Empty server field: &#39;&lt;field&gt;&#39;. AsyncAPI requires a value for this field on every server. This @server was dropped.</p></blockquote><p><code>host</code> or <code>protocol</code> is blank, or holds only spaces. Both are required by the Server Object. A blank value passes the type check but makes the document invalid, so the whole server is dropped.</p><p><strong>Fix:</strong> Give the field a real value.</p><h3 id="invalid-server-name" tabindex="-1"><code>invalid-server-name</code> <a class="header-anchor" href="#invalid-server-name" aria-label="Permalink to &quot;`invalid-server-name`&quot;">​</a></h3><blockquote><p>Invalid server name: &#39;&lt;name&gt;&#39;. AsyncAPI only allows letters, digits, &#39;_&#39;, and &#39;-&#39; in a server name. This @server was dropped.</p></blockquote><p>The name is outside the character set AsyncAPI allows for a key of the root <code>servers</code> map. This set is stricter than the one for the Components Object. A dot is not allowed here.</p><p><strong>Fix:</strong> Use a name that only holds letters, digits, <code>_</code>, and <code>-</code>. The emitter never rewrites the name, because that would silently change the key you asked for.</p><h2 id="warnings" tabindex="-1">Warnings <a class="header-anchor" href="#warnings" aria-label="Permalink to &quot;Warnings&quot;">​</a></h2><h3 id="message-key-shadows-schema-key" tabindex="-1"><code>message-key-shadows-schema-key</code> <a class="header-anchor" href="#message-key-shadows-schema-key" aria-label="Permalink to &quot;`message-key-shadows-schema-key`&quot;">​</a></h3><blockquote><p>Message name &#39;&lt;name&gt;&#39; is also the components.schemas key of a different type, so a reader can misread this message as describing that type. A message key drops the namespace prefix that a schema key keeps, which makes the two overlap. Pass a different name to @message.</p></blockquote><p>The document stays valid — <code>components.messages</code> and <code>components.schemas</code> are separate maps, so nothing actually collides. The risk is to the reader: <code>components.messages.Sales.Ev</code> and <code>components.schemas[&quot;Sales.Ev&quot;]</code> look like the same thing while describing different types.</p><p><strong>Fix:</strong> pass a different name to <code>@message</code>.</p><h3 id="sanitized-message-key" tabindex="-1"><code>sanitized-message-key</code> <a class="header-anchor" href="#sanitized-message-key" aria-label="Permalink to &quot;`sanitized-message-key`&quot;">​</a></h3><blockquote><p>Message name &#39;&lt;requested&gt;&#39; is not a legal components.messages key, so it was emitted as &#39;&lt;emitted&gt;&#39;. A key may only use the characters a-z, A-Z, 0-9, &#39;.&#39;, &#39;-&#39;, and &#39;_&#39;.</p></blockquote><p>The name given to <code>@message</code> falls outside the Components Object key charset, so the emitter encoded the offending characters. The emitted key is therefore not the string that was asked for.</p><p><strong>Fix:</strong> pass a name that only uses <code>a-z</code>, <code>A-Z</code>, <code>0-9</code>, <code>.</code>, <code>-</code>, and <code>_</code>.</p><h3 id="nested-header-ignored" tabindex="-1"><code>nested-header-ignored</code> <a class="header-anchor" href="#nested-header-ignored" aria-label="Permalink to &quot;`nested-header-ignored`&quot;">​</a></h3><blockquote><p>This @header marks a property that is not a top-level field of a @message model, so it stays in the payload schema. Only a top-level field is lifted into <code>headers</code>. Move the property to the message model, or describe the whole headers object with @headers.</p></blockquote><p><code>@header</code> marks a property the emitter cannot lift: it sits inside a model that a payload refers to, rather than on the message model itself. The payload of a message is one object, and its headers are a sibling of that object. A field two levels down has no such sibling to move to, and lifting it would silently restructure the payload around it. <code>@typespec/http</code> reads metadata off the top level for the same reason.</p><p><strong>Fix:</strong> move the property to the message model, or describe the whole headers object with <code>@headers</code>.</p><h3 id="inherited-header-ignored" tabindex="-1"><code>inherited-header-ignored</code> <a class="header-anchor" href="#inherited-header-ignored" aria-label="Permalink to &quot;`inherited-header-ignored`&quot;">​</a></h3><blockquote><p>This @header marks a property that &#39;&lt;message&gt;&#39; inherits through &#39;extends&#39;, so it stays in the payload schema. Only a property the message model declares itself is lifted into <code>headers</code>. Spread the base model with &#39;...&#39; instead of extending it, or describe the whole headers object with @headers.</p></blockquote><p><code>@header</code> marks a property that the message inherits through <code>extends</code>. Such a property is a top-level field of the emitted payload, so this case gets its own message rather than the one above.</p><p>A base model is a declaration of its own, shared by every model that extends it, and the payload refers to it through <code>allOf</code>. Lifting a field out of it would change every other user of that base model too. A spread, <code>...Base</code>, copies the properties into the message model instead, so those fields are the message&#39;s own and they are lifted.</p><p><strong>Fix:</strong> spread the base model with <code>...</code>, or describe the whole headers object with <code>@headers</code>.</p><h3 id="server-outside-service" tabindex="-1"><code>server-outside-service</code> <a class="header-anchor" href="#server-outside-service" aria-label="Permalink to &quot;`server-outside-service`&quot;">​</a></h3><blockquote><p>Server &#39;&lt;name&gt;&#39; on namespace &#39;&lt;namespace&gt;&#39; was dropped. This emitter reads the servers of the service namespace only. Move this @server to the service namespace this document is emitted from.</p></blockquote><p><code>@server</code> is applied to a namespace that is not the service namespace this document comes from. The emitter reads servers from the service namespace only, the same source as <code>info</code>.</p><p><strong>Fix:</strong> Move the <code>@server</code> to the service namespace, or use <code>@@server</code> to augment it from where you are.</p><h3 id="multiple-services" tabindex="-1"><code>multiple-services</code> <a class="header-anchor" href="#multiple-services" aria-label="Permalink to &quot;`multiple-services`&quot;">​</a></h3><blockquote><p>Multiple services found. AsyncAPI only supports one service per document. The first one will be used.</p></blockquote><p>More than one namespace carries <code>@service</code>. The emitter uses the first and ignores the rest.</p><p><strong>Fix:</strong> keep one <code>@service</code> per compilation, or split services into separate <code>tsp compile</code> runs.</p><h3 id="unserializable-example" tabindex="-1"><code>unserializable-example</code> <a class="header-anchor" href="#unserializable-example" aria-label="Permalink to &quot;`unserializable-example`&quot;">​</a></h3><blockquote><p>This @example could not be serialized to JSON and was omitted from the emitted schema.</p></blockquote><p>An <code>@example</code> value contains something the compiler cannot serialize to plain JSON (an unsupported scalar constructor, a malformed <code>duration.fromISO(...)</code> value, ...). The example is dropped; the schema itself is unaffected.</p><p><strong>Fix:</strong> simplify the example value to JSON-representable parts.</p><h3 id="unserializable-message-example" tabindex="-1"><code>unserializable-message-example</code> <a class="header-anchor" href="#unserializable-message-example" aria-label="Permalink to &quot;`unserializable-message-example`&quot;">​</a></h3><blockquote><p>This @messageExample could not be serialized to JSON and was dropped from the emitted message.</p></blockquote><p>A <code>@messageExample</code> value contains something the compiler cannot serialize to plain JSON (an unsupported scalar constructor, a malformed <code>duration.fromISO(...)</code> value, ...). The whole entry is dropped, including its serializable sibling fields. An entry that kept half its payload would show a message the application never sends.</p><p><strong>Fix:</strong> simplify the example value to JSON-representable parts.</p><h3 id="unrepresentable-numeric-constraint" tabindex="-1"><code>unrepresentable-numeric-constraint</code> <a class="header-anchor" href="#unrepresentable-numeric-constraint" aria-label="Permalink to &quot;`unrepresentable-numeric-constraint`&quot;">​</a></h3><blockquote><p>This @&lt;decorator&gt; constraint could not be represented as a JSON number (its value overflows or loses precision as a JS number) and was omitted from the emitted schema.</p></blockquote><p>A <code>@minValue</code>/<code>@maxValue</code>/<code>@minLength</code>/... bound overflows or loses precision as a JavaScript number — e.g. <code>@maxValue(9223372036854775807)</code> on an <code>int64</code>. The keyword is omitted rather than emitted with a corrupted value.</p><p><strong>Fix:</strong> use a bound that fits exactly in a double (up to ±2^53), or drop the constraint.</p><h3 id="unsupported-temporal-range-constraint" tabindex="-1"><code>unsupported-temporal-range-constraint</code> <a class="header-anchor" href="#unsupported-temporal-range-constraint" aria-label="Permalink to &quot;`unsupported-temporal-range-constraint`&quot;">​</a></h3><blockquote><p>This @&lt;decorator&gt; constraint targets a date/time/duration value, which draft-07 JSON Schema cannot express as a <code>minimum</code>/<code>maximum</code>, and was omitted from the emitted schema.</p></blockquote><p><code>@minValue</code>/<code>@maxValue</code> on a temporal scalar (<code>utcDateTime</code>, <code>plainDate</code>, <code>duration</code>, ...). Those emit as <code>type: string</code> schemas, and draft-07 has no keyword to bound a string-typed date.</p><p><strong>Fix:</strong> remove the constraint, or express it as documentation (<code>@doc</code>).</p><h3 id="missing-discriminator-property" tabindex="-1"><code>missing-discriminator-property</code> <a class="header-anchor" href="#missing-discriminator-property" aria-label="Permalink to &quot;`missing-discriminator-property`&quot;">​</a></h3><blockquote><p>@discriminator(&quot;&lt;property&gt;&quot;) names a property that is not defined on this model. AsyncAPI requires the discriminating property to be defined here, so <code>discriminator</code> was omitted from the emitted schema.</p></blockquote><p><strong>Fix:</strong> declare the named property on the model (or an ancestor), or fix the property name in <code>@discriminator</code>. Note it must be the <strong>TypeSpec</strong> property name, not an <code>@encodedName</code> wire name.</p><h3 id="optional-discriminator-property" tabindex="-1"><code>optional-discriminator-property</code> <a class="header-anchor" href="#optional-discriminator-property" aria-label="Permalink to &quot;`optional-discriminator-property`&quot;">​</a></h3><blockquote><p>@discriminator(&quot;&lt;property&gt;&quot;) names a property that is optional on this model. AsyncAPI requires the discriminating property to be required, so <code>discriminator</code> was omitted from the emitted schema.</p></blockquote><p><strong>Fix:</strong> make the discriminating property required (remove the <code>?</code>).</p><h3 id="encoded-name-override-conflict" tabindex="-1"><code>encoded-name-override-conflict</code> <a class="header-anchor" href="#encoded-name-override-conflict" aria-label="Permalink to &quot;`encoded-name-override-conflict`&quot;">​</a></h3><p>An overriding property&#39;s <code>@encodedName</code> differs from the same-named ancestor property&#39;s wire name. The usual <code>allOf: [$ref Base, own]</code> shape would then require <strong>both</strong> wire names at once, rejecting every valid payload. The emitter flattens the model&#39;s schema instead (inherited properties inlined, no <code>$ref</code> to the base).</p><p><strong>Fix:</strong> give the override the same <code>@encodedName</code> as the ancestor&#39;s, or rename at one level only.</p><h3 id="never-typed-property-override" tabindex="-1"><code>never-typed-property-override</code> <a class="header-anchor" href="#never-typed-property-override" aria-label="Permalink to &quot;`never-typed-property-override`&quot;">​</a></h3><p>A property is declared <code>never</code> to remove an inherited property, but the base&#39;s <code>$ref</code> branch would still require it. As above, the emitter flattens the schema (with the <code>never</code>-typed property omitted).</p><p><strong>Fix:</strong> none needed if flattening is acceptable — this warning documents the shape change. Otherwise restructure the hierarchy so the property isn&#39;t inherited in the first place.</p>',140)])])}const u=o(s,[["render",n]]);export{m as __pageData,u as default};
